//! Icons: Lucide's outlines (ISC licence, https://lucide.dev), stroked like
//! Lucide's SVGs – a 24-unit box, round caps and joins. The drawings are
//! [`IconNode`]s, generated by `tools/lucide-icons.py` for the icons an app
//! uses ([`crate::lucide`] has the toolkit's own); [`Icon`] shows one.

use reactive_graph::traits::Track;
use vello_cpu::RenderContext;
use vello_cpu::kurbo::{
    Affine, BezPath, Cap, Circle, Ellipse, Join, Point, Rect, RoundedRect, Shape, Size, Stroke,
};

use crate::i18n::{IntoText, TextProp};
use crate::paint::TOLERANCE;
use crate::reactive::{MountCx, Watch};
use crate::theme::{Color, TextRole, Theme};
use crate::widget::{
    Available, Change, Known, LayoutCx, PaintCx, Widget, WidgetId, accessible_rect,
};

/// One part of an icon, in Lucide's 24×24 box – the SVG elements Lucide uses
#[derive(Clone, Copy, Debug)]
pub enum Part {
    Path(&'static str),
    Circle {
        cx: f64,
        cy: f64,
        r: f64,
    },
    Ellipse {
        cx: f64,
        cy: f64,
        rx: f64,
        ry: f64,
    },
    Rect {
        x: f64,
        y: f64,
        width: f64,
        height: f64,
        r: f64,
    },
    Line {
        x1: f64,
        y1: f64,
        x2: f64,
        y2: f64,
    },
    /// `polyline`, or `polygon` when closed
    Poly {
        points: &'static [(f64, f64)],
        closed: bool,
    },
}

/// An icon's drawing: one of Lucide's (generated by `tools/lucide-icons.py`, see
/// [`crate::lucide`]) or an own one in the same 24-unit box
#[derive(Clone, Copy, Debug)]
pub struct IconNode(pub &'static [Part]);

impl IconNode {
    /// The outline in the 24-unit box
    pub fn path(&self) -> BezPath {
        let mut out = BezPath::new();
        for part in self.0 {
            match *part {
                Part::Path(d) => {
                    // the data is ours and known to parse; a bad path would only lose that stroke
                    if let Ok(p) = BezPath::from_svg(d) {
                        out.extend(p);
                    }
                }
                Part::Circle { cx, cy, r } => {
                    out.extend(Circle::new((cx, cy), r).path_elements(TOLERANCE))
                }
                Part::Ellipse { cx, cy, rx, ry } => {
                    out.extend(Ellipse::new((cx, cy), (rx, ry), 0.0).path_elements(TOLERANCE))
                }
                Part::Rect {
                    x,
                    y,
                    width,
                    height,
                    r,
                } => out.extend(
                    RoundedRect::new(x, y, x + width, y + height, r).path_elements(TOLERANCE),
                ),
                Part::Line { x1, y1, x2, y2 } => {
                    out.move_to((x1, y1));
                    out.line_to((x2, y2));
                }
                Part::Poly { points, closed } => {
                    for (i, &p) in points.iter().enumerate() {
                        if i == 0 {
                            out.move_to(p);
                        } else {
                            out.line_to(p);
                        }
                    }
                    if closed {
                        out.close_path();
                    }
                }
            }
        }
        out
    }

    /// Strokes the icon into `rect` (square), `stroke` in the icon's 24-unit box,
    /// turned by `degrees` and scaled by `scale` about its centre
    pub fn draw(
        &self,
        ctx: &mut RenderContext,
        rect: Rect,
        stroke: f64,
        color: Color,
        degrees: f64,
        scale: f64,
    ) {
        let base = *ctx.transform();
        let c = rect.center();
        let fit = rect.width() / 24.0;
        let t = Affine::translate(c.to_vec2())
            * Affine::rotate(degrees.to_radians())
            * Affine::scale(fit * scale)
            * Affine::translate(-Point::new(12.0, 12.0).to_vec2());
        ctx.set_transform(base * t);
        ctx.set_stroke(
            Stroke::new(stroke)
                .with_caps(Cap::Round)
                .with_join(Join::Round),
        );
        ctx.set_paint(color);
        ctx.stroke_path(&self.path());
        ctx.set_transform(base);
    }
}

/// Lucide's stroke width in Kiesel (`stroke-width: 1.75`)
pub const STROKE: f64 = 1.75;

/// Which colour an icon takes – on the web it inherits the text's
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Tone {
    /// The colour of text in this role (body text: `--ksl-text-2`)
    Text(TextRole),
    /// `--ksl-icon`: icons that stand on their own
    #[default]
    Icon,
    Accent,
}

impl Tone {
    pub fn color(self, theme: &Theme) -> Color {
        match self {
            Tone::Text(role) => theme.text_color(role),
            Tone::Icon => theme.icon,
            Tone::Accent => theme.accent,
        }
    }
}

/// A line icon: `Icon::new(lucide::SEARCH)`. Decorative unless it has a label.
pub struct Icon {
    id: WidgetId,
    node: IconNode,
    /// Edge length in px; `None`: 1.25 em, growing with the text
    size: Option<f64>,
    tone: Tone,
    label: Option<TextProp>,
    watch: Option<Watch>,
    bounds: Rect,
}

impl Icon {
    pub fn new(node: IconNode) -> Self {
        Self {
            id: WidgetId::next(),
            node,
            size: None,
            tone: Tone::default(),
            label: None,
            watch: None,
            bounds: Rect::ZERO,
        }
    }

    /// Edge length in logical px (default 1.25 em: 20 px at the default text size)
    pub fn size(mut self, px: f64) -> Self {
        self.size = Some(px);
        self
    }

    pub fn tone(mut self, tone: Tone) -> Self {
        self.tone = tone;
        self
    }

    /// What it means, for assistive technology: an icon that says something on
    /// its own (not next to text that says it already)
    pub fn label(mut self, label: impl IntoText) -> Self {
        self.label = Some(TextProp::new(label));
        self
    }

    fn edge(&self, theme: &Theme) -> f64 {
        self.size
            .unwrap_or(1.25 * f64::from(theme.metrics.font_size))
    }
}

impl Widget for Icon {
    fn id(&self) -> WidgetId {
        self.id
    }

    fn mount(&mut self, cx: &mut MountCx<'_>) {
        if let Some(label) = &self.label {
            let label = label.signal();
            self.watch = Some(cx.watch(self.id, move || label.track()));
        }
    }

    fn update(&mut self, _cx: &mut LayoutCx<'_>) -> Change {
        if self.label.as_mut().is_some_and(TextProp::refresh) {
            Change::PAINT
        } else {
            Change::NONE
        }
    }

    fn measure(&mut self, cx: &mut LayoutCx<'_>, _known: Known, _available: Available) -> Size {
        let edge = self.edge(cx.theme);
        Size::new(edge, edge)
    }

    fn style(&self, _theme: &Theme) -> taffy::Style {
        taffy::Style {
            flex_shrink: 0.0,
            ..Default::default()
        }
    }

    fn set_bounds(&mut self, _cx: &mut LayoutCx<'_>, bounds: Rect) {
        self.bounds = bounds;
    }

    fn bounds(&self) -> Rect {
        self.bounds
    }

    /// Round caps reach half a stroke past the box
    fn ink(&self) -> Rect {
        self.bounds.inflate(2.0, 2.0)
    }

    fn paint(&self, cx: &mut PaintCx<'_>) {
        let edge = self.bounds.width().min(self.bounds.height());
        let square = Rect::from_center_size(self.bounds.center(), (edge, edge));
        self.node
            .draw(cx.ctx, square, STROKE, self.tone.color(cx.theme), 0.0, 1.0);
    }

    fn accessibility(&self) -> Option<accesskit::Node> {
        let label = self.label.as_ref().filter(|l| !l.shown.is_empty())?;
        let mut node = accesskit::Node::new(accesskit::Role::Image);
        node.set_label(label.shown.clone());
        node.set_bounds(accessible_rect(self.bounds));
        Some(node)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lucide_paths_parse_and_fit_the_box() {
        for icon in crate::lucide::ALL {
            for part in icon.0 {
                if let Part::Path(d) = part {
                    assert!(BezPath::from_svg(d).is_ok(), "{d}");
                }
            }
            let b = icon.path().bounding_box();
            assert!(
                b.x0 >= 1.9 && b.y0 >= 1.9 && b.x1 <= 22.1 && b.y1 <= 22.1,
                "{b:?}"
            );
        }
    }
}
